"""Structural contract shared by drivers; timestamps are monotonic seconds.

Callbacks execute on the runtime event loop. Each sample has six SI values:
acceleration (m/s²) followed by angular velocity (rad/s). Drivers own BLE tasks;
explicit disconnect must stop retries and drain them before returning.
"""
from typing import Protocol


class RingDriver(Protocol):
    address: str
    connected: bool
    is_reconnecting: bool
    battery_level: int
    start_calib_timestamps: list[float]
    end_calib_timestamps: list[float]
    ring_timestamps: list[float]
    end_indices: list[int]

    async def connect(self) -> None: ...
    async def disconnect(self) -> None: ...
    async def open_imu(self) -> None: ...
    def set_auto_reconnect(self, enabled: bool) -> None: ...
    def to_host_timestamp(self, timestamp: float) -> float: ...
    async def calib_time(self, index: int) -> None: ...
    def reset_time_calib_data(self) -> None: ...
    def clear_time_calibration(self) -> None: ...
    def set_time_calibration(self, intercept: float, slope: float) -> None: ...
